function shell(screen){const projectScope=screen.scope==='project',p=T.project();return `<aside class="sidebar" id="sidebar"><button class="brand" data-go="today" aria-label="tie, главная">tie<span class="rings"></span></button><button class="mobile-close icon-btn" data-action="core-menu" aria-label="Закрыть меню">${T.icon('close')}</button><nav aria-label="Основная навигация">${(T.state.role==='couple'?[['Ваша свадьба',[['overview','Наша свадьба','heart'],['tasks','План подготовки','check'],['approvals','Согласования','check-circle'],['guests','Гости','users'],['finance','Финансы','chart'],['guest','Сайт свадьбы','external']]]]:agencyNav).map(([name,items])=>`<div class="nav-group"><div class="nav-label">${name}</div>${items.map(([route,label,icon])=>`<button class="nav-item ${T.state.route===route||projectScope&&route==='projects'?'active':''}" data-go="${route}">${T.icon(icon)}<span>${label}</span>${route==='applications'?'<b>4</b>':''}</button>`).join('')}</div>`).join('')}</nav><div class="sidebar-bottom"><button class="nav-item" data-go="public">${T.icon('external')}<span>Сайт агентства</span></button><div class="sidebar-caption">Свадьба, собранная вместе</div></div></aside><div class="sidebar-scrim" data-action="core-menu"></div><div class="main-column"><header class="topbar"><div class="inline"><button class="icon-btn mobile-menu" data-action="core-menu" aria-label="Открыть меню">${T.icon('menu')}</button><button class="global-search" data-action="core-search" aria-label="Поиск в пространстве">${T.icon('search')}<span>Найти в пространстве</span><kbd>⌘ K</kbd></button></div><div class="inline topbar-right"><button class="icon-btn notification-button" data-go="notifications" aria-label="Уведомления">${T.icon('bell')}<i></i></button><button class="profile-button" data-go="profile" aria-label="Мой профиль">${T.avatar(T.state.role==='couple'?'Алина Соколова':'Мария Соколова')}<span>${T.state.role==='couple'?'Алина':'Мария Соколова'}</span>${T.icon('chevron',14)}</button></div></header><main id="content" class="workspace">${projectScope?`<div class="project-context"><button class="back-link" data-go="projects">← Все свадьбы</button><div class="project-title-row"><div><div class="inline"><h2>${esc(p.name)}</h2>${T.badge(p.status,'green')}</div><p>${esc(p.date)} <span>·</span> ${esc(p.venue)} <span class="rose">${p.id==='p1'?'· осталось 10 дней':p.id==='p2'?'· осталось 31 день':p.id==='p3'?'· осталось 66 дней':''}</span></p></div><button class="icon-btn" data-go="project-settings" aria-label="Настройки свадьбы">${T.icon('settings')}</button></div><nav class="project-tabs" aria-label="Разделы свадьбы">${tabs.map(([route,label])=>`<button data-go="${route}" class="${(screen.tab||T.state.route)===route?'active':''}">${label}</button>`).join('')}</nav></div>`:''}${screen.render()}</main>${projectScope?`<nav class="bottom-nav" aria-label="Быстрая навигация">${[['overview','Обзор','home'],['tasks','План','check'],['approvals','Решения','check-circle'],['more','Ещё','grid']].map(([route,label,icon])=>`<button data-go="${route}" class="${(screen.tab||T.state.route)===route?'active':''}">${T.icon(icon)}${label}</button>`).join('')}</nav>`:''}</div>`}
function render(){T.closeModal();const route=location.hash.slice(1)||'today';T.state.route=T.screens[route]?route:'today';const screen=T.screens[T.state.route];if(!screen)return;document.title=`${screen.title} — tie · макет`;document.body.classList.remove('menu-open');document.body.classList.toggle('public-mode',screen.scope==='public');document.body.classList.toggle('project-mode',screen.scope==='project');$('#app').innerHTML=screen.scope==='public'?screen.render():shell(screen);$('#preview-mode').value=T.state.mode;$('#preview-role').value=T.state.role;window.scrollTo(0,0);screen.onMount?.();}
T.actions['core-close']=()=>T.closeModal();T.actions['core-menu']=()=>document.body.classList.toggle('menu-open');
T.actions['core-search']=()=>{const routes=Object.entries(T.screens).filter(([,s])=>s.scope!=='public');T.modal({title:'Поиск в пространстве',body:`<label class="field"><span>Раздел, свадьба или действие</span><input id="global-query" placeholder="Например: гости или финансы" autofocus></label><div class="search-results">${routes.map(([id,s])=>`<button data-go="${id}" data-search-text="${esc(s.title.toLowerCase())}">${T.icon('arrow')}<span>${esc(s.title)}</span><small>${s.scope==='project'?'Свадьба':'Агентство'}</small></button>`).join('')}</div>`,onMount:root=>root.querySelector('#global-query').addEventListener('input',e=>root.querySelectorAll('[data-search-text]').forEach(x=>x.hidden=!x.dataset.searchText.includes(e.target.value.toLowerCase())))})};
